import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { changePasswordHandler } from "../handlers/changePasswordHandler";
import type { ApiError } from "../runtime/client";
import type { ChangePasswordRequest } from "../types/ChangePasswordRequest";

type Data = Awaited<ReturnType<typeof changePasswordHandler>>;
type Vars = ChangePasswordRequest;

export function useChangePassword(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => changePasswordHandler(vars),
    ...options,
  });
}
